CREATE TABLE CORE.T_FACT_CUSTOMER_ORDER_LINE_2 (
   CUST_ORDER_POS_NR                   NUMERIC(38,0)   NOT NULL COMMENT 'The particular position number of an item_2 in an order',
   CUST_ORDER_SID                      NUMERIC         NOT NULL COMMENT 'The unique identifier (surrogate key) for customer order',
   PROD_VARIANT_SID                    NUMERIC         COMMENT 'Ordered product',
   PROD_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the product',
   CUST_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the customer',
   WH_SID                              NUMERIC         COMMENT 'The unique identifier (sk) for the warehouse from where particular product will be sent',
   WSHOP_CD                            VARCHAR(5)      COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer. The webshop is defined per political country.',
   CURR_CD                             VARCHAR(5)      COMMENT 'The code identifying the currency according to ISO-4217.',
   TAX_CLASS_CD                        VARCHAR(5)      COMMENT 'The code identifying the tax class',
   DELIVERY_CUST_SID                   NUMERIC         COMMENT 'Customer to whom the order was delivered ',
   DELIVERY_ADDR_SID                   NUMERIC         COMMENT 'The unique identifier (sk) for the delivery address_2 where original order was delivered',
   BILLING_ADDR_SID                    NUMERIC         COMMENT 'The unique identifier (sk) for the billing address_2',
   ORDER_CANCEL_STATUS_CD              VARCHAR(5)      COMMENT 'The code for the status_2 of cancellation',
   CUST_PAYM_METHOD_CD                 VARCHAR(5)      COMMENT 'Unique code of the payment method',
   SALES_CHANNEL_TYPE_CD               VARCHAR(5)      COMMENT 'The code for the device which was being used to order from the online webshop. Possible values are desktop browser, iOS or Android.',
   ORDER_CANCEL_REASON_CD              VARCHAR(5)      COMMENT 'The code for reason why the customer has cancelled or got been cancelled an order line/product',
   CUST_ORDER_TYPE_CD                  VARCHAR(5)      COMMENT 'This field contains codes for different credit notes for orders, for example ZRPL for replacement order and ZWSO for webshop sales_2 order and so on.',
   PROD_ASSORTMENT_CLASS_CD            VARCHAR(5)      COMMENT 'The code for the indicating if product variant is a part of special offer or normal or special assortiment',
   SALES_SEGMENT_TYPE_CD               VARCHAR(20)     COMMENT 'The sales_2 channel name',
   ORDER_REASON_CD                     VARCHAR(5)      COMMENT 'Order reason code on order document level ( 008 guter Service ,etc)',
   DELIVERY_SRC_TYPE_CD                VARCHAR(5)      COMMENT 'The code for source location_2 of product from where it is delivered i.e. from supplier_2 or warehouse directly',
   DELIVERY_BLOCKED_REASON_CD          VARCHAR(5)      COMMENT 'The code with the reason why the delivery is blocked for the specific customer order.',
   CUST_ORDER_CREATE_TMSP              TIMESTAMP_TZ(9) COMMENT 'The timestamp when order was created in source ERP system ( is used in reporting)',
   CUST_ORDER_DT                       DATE            COMMENT 'The date when order was made ( when customer created the order )',
   CUST_ORDER_TM                       TIME(9)         COMMENT 'Time when order was made ( when customer created the order )',
   CUST_ORDER_NR                       VARCHAR(20)     NOT NULL COMMENT 'The original order number of the source system',
   PROD_QTY                            NUMERIC(38,5)   COMMENT 'Quantity of a particular product ordered',
   IS_BUNDLE_HEADER_FG                 BOOLEAN         COMMENT 'Indicates if position represents a bundle header ( null in all the other cases)',
   BUNDLE_HEADER_POS_NR                NUMERIC(38,0)   COMMENT 'In case of a line being a composition part of the bundle-header (see bundle header code field), it can be allocated with this field to its header item_2',
   IS_REPLACEMENT_ORDER_FG             BOOLEAN         COMMENT 'An indicator showing if the order is a replacement_order or not',
   REF_CUST_ORDER_SID                  NUMERIC         COMMENT 'The unique identifier for the reference customer order. In case the order is a replacement order, the reference customer order is the original order',
   REF_CUST_ORDER_NR                   VARCHAR(20)     COMMENT 'The original order number of the customer document. In case the order is a replacement order, the reference customer order is the original order',
   REF_CUST_ORDER_POS_NR               NUMERIC(38,0)   COMMENT 'The particular order position number of the reference customer. In case the order is a replacement order, the reference customer order is the original order',
   PROD_PRICE_NET_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Original (listed) net price of a product in local currency',
   PROD_PRICE_GROSS_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Original (listed) gross price of a product in local currency',
   PROD_PRICE_VAT_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Original (listed) vat value on price of a product in local currency',
   PROD_COUPON_NET_LOCAL_VAL           NUMERIC(38,5)   COMMENT 'The net discount value for the (original/listed) product in local currency',
   PROD_COUPON_GROSS_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'The gross discount value for the (original/listed) product in local currency',
   PROD_COUPON_VAT_LOCAL_VAL           NUMERIC(38,5)   COMMENT 'The discount vat value for the (original/listed) product in local currency',
   DELIVERY_COST_NET_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'Article specific net delivery cost in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs',
   DELIVERY_COST_GROSS_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'Article specific gross delivery cost in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COST_VAT_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'Article specific delivery vat value in local currency. This tax value is optional and mostly article dependent. An example is a fridge which has additional delivery costs for which taxes might have to be paid',
   DELIVERY_COUPON_NET_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'The net discount value for article specific delivery costs in local currency.',
   DELIVERY_COUPON_GROSS_LOCAL_VAL     NUMERIC(38,5)   COMMENT 'The gross discount value for article specific delivery costs in local currency.',
   DELIVERY_COUPON_VAT_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'The discount vat value for article specific delivery costs in local currency',
   DELIVERY_PAUSHAL_NET_LOCAL_VAL      NUMERIC(38,5)   COMMENT 'A paushal for delivery costs splitted per every order position in netto and local currency',
   DELIVERY_PAUSHAL_GROSS_LOCAL_VAL    NUMERIC(38,5)   COMMENT 'A paushal for delivery costs splitted per every order position in gross and local currency',
   DELIVERY_PAUSHAL_VAT_LOCAL_VAL      NUMERIC(38,5)   COMMENT 'The vat value of the paushal delivery costs splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_NET_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional net delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency.',
   ADD_DELIVERY_PAUSHAL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Additional gross delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_VAT_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional vat on delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount value netto for paushal delivery cost splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount value gross for paushal delivery cost splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount vat value for paushal delivery cost splitted per every order position in local currency',
   IVP_PRICE_NET_LOCAL_VAL             NUMERIC(38,5)   COMMENT 'Internal invoice price in local currency  netto',
   GLD_PRICE_NET_LOCAL_VAL             NUMERIC(38,5)   COMMENT 'Moving average price in local currency netto',
   GLD_UNIT_PRICE_NET_EUR_VAL          NUMERIC(38,5)   COMMENT 'The gld unit_2 price in sales_2 order line in euros for internal margin calculations',
   IVP_ORIGINAL_PRICE_NET_LOCAL_VAL    NUMERIC(38,5)   COMMENT 'Internal invoice price in local currency  netto ( may be null and is used in calculation of ivp_price_net_local_val )',
   IVP_UNIT_PRICE_NET_EUR_VAL          NUMERIC(38,5)   COMMENT 'This field is a derived one based on ivp_original_unit_price_net_eur_val and gld_unit_price_net_eur_val',
   IVP_ORIGINAL_UNIT_PRICE_NET_EUR_VAL NUMERIC(38,5)   COMMENT 'The ivp original unit_2 prices in sales_2 order line in euros for internal margin calculations',
   COGS_PRICE_NET_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Cost-of-Goods-sold, short: CoGs. Needed for calc of margin (= revenue - cogs )',
   GROSS_MARGIN_NET_EUR_VAL            NUMERIC(38,5)   COMMENT 'Calculated Net Profit Margin in EUR',
   EKP_UNIT_PRICE_NET_EUR_VAL          NUMERIC(38,5)   COMMENT 'Latest EKP (Purchase Price) value in EUR per unit_2',
   ADD_SERVICES_VAT_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Vat Revenue in local currency coming from additional services (delivery_to_point_of_use / assembly). This cost is optional and mostly article dependent.',
   ADD_SERVICES_GROSS_LOCAL_VAL        NUMERIC(38,5)   COMMENT 'Gross Revenue in local currency coming from additional services (delivery_to_point_of_use / assembly). This cost is optional and mostly article dependent.',
   ADD_SERVICES_NET_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Net Revenue in local currency coming from additional services (delivery_to_point_of_use / assembly). This cost is optional and mostly article dependent.',
   IS_BLOCKED_DELIVERY_FG              BOOLEAN         COMMENT 'Flag which tells whether a delivery is being blocked currently. e.g. if customer orders with payment type \"Vorauskasse\" then the delivery will only start as soon as the money arrives',
   IS_ORDER_CANCEL_FG                  BOOLEAN         COMMENT 'Flag telling whether the order position has been cancelled. Customers can cancel orders only completely or not at all. Lidl Digital''s Call Center has the possibility to cancel single positions though. Therefore the position''s flag within an order has the same value mostly, but can be different values in rare cases.',
   CUST_ORDER_PERFORM_DT               DATE            COMMENT 'The timestamp when the delivery to the customer actually started. This timestamp is relevant from a financial perspective as until then you are not allowed to charge him/her. In case of serveral performance timestamps for a single article within a single order the last date is picked.',
   CUST_DELIVERY_TGT_DT                DATE            COMMENT 'The first date which has been communicated to the customer for the expected delivery',
   WH_CD                               VARCHAR(5)      COMMENT 'The code for the warehouse from where particular product will be sent',
   DROPSHIPMENT_ORDER_FG               BOOLEAN         COMMENT 'In case the material is being sent from the supplier_2 this field will be filled.',
   IS_PART_OF_BUNDLE_HEADER_CNT_FG     BOOLEAN         COMMENT 'Reporting relevant - if report uses the bundle header count use this flag. Set as ''true'' for bundle header and non-bundle item_2 and ''false'' for bundle position item_2 ',
   IS_PART_OF_BUNDLE_POS_CNT_FG        BOOLEAN         COMMENT 'Reporting relevant - if report uses the bundle header count use this flag. Set as ''true'' for bundle position and non-bundle item_2 and ''false'' for bundle header item_2 ',
   IS_LEGACY_FG                        BOOLEAN         COMMENT 'Technical field used to identify legacy data (from Qlik legacy systems vs_2 generic data flows), for further use as a filter condition',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   PROD_NR                             VARCHAR(20)     COMMENT 'The number for internal onlineshop product, which is country_2 independent',
   PROD_SALE_TYPE_CD                   VARCHAR(5)      COMMENT 'This code shows if the product is sold as a single item_2 (SI), group article header (GH) - also referred to as "bundle header", or as a group article component (GC) - also referred to as "bundle component"',
   DIST_CHANNEL_CD                     VARCHAR(5)      COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
   DIST_CHANNEL_TYPE_CD                VARCHAR(5)      COMMENT 'A  type of distribution channel ( Wshop for LD Webshop , IC for Intercompany)',
   DIST_COUNTRY_CD                     VARCHAR(5)      COMMENT 'The unique code for a country_2 according to ISO-3166 Alpha-2. E.g. \"DE\" for Germany or \"FR\" for France',
   DIST_ZONE_CD                        VARCHAR(5)      COMMENT 'The unique code for a distribution zone ( f.e. BAL , CAN, etc)',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_FACT_CUSTOMER_ORDER_LINE PRIMARY KEY (CUST_ORDER_SID, CUST_ORDER_POS_NR) NOT ENFORCED 
)  COMMENT = 'The orderlines of the orders placed from a customer within the onlineshops to receive the wanted items. An orderline corresponds to the lines shown to the customer in the order confirmation, i. e. if more than one item_2 of a kind is ordered it is represented by a number. Such orders can be also cancelled, returned or free resends to customers. The T_FACT_CUSTOMER_RETURN_LINE_2 holds detailed information about returns. In the stationary business this is equivalent to receipts lines on a ticket. Special attention is needed since both bundle items and the individual items within a bundle are in this table, hence appropriate filtering is needed while using this table.';
